{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

function fail(msg) {
  process.stderr.write(`error: ${msg}\n`)
  process.exit(2)
}

function changesOf(base, side) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const out = []
  let i = 0, j = 0, bs = 0, ss = 0
  const flush = () => {
    if (i > bs || j > ss) out.push({ bs, be: i, ss, se: j })
  }
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      flush()
      i++; j++; bs = i; ss = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n; j = m
  flush()
  return out
}

function eq(a, b) {
  return a.length === b.length && a.every((x, k) => x === b[k])
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !['merge', 'merge2', 'regions'].includes(args[0])) fail('usage: cli.js merge|merge2|regions')
  const mode = args[0]
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const docs = [[]]
  for (const l of lines) {
    if (l === '%%%') docs.push([])
    else docs[docs.length - 1].push(l)
  }
  if (docs.length !== 3) fail('expected three parts separated by %%%')
  const [mine, base, theirs] = docs

  const all = [
    ...changesOf(base, mine).map(c => ({ ...c, who: 0 })),
    ...changesOf(base, theirs).map(c => ({ ...c, who: 1 })),
  ]
  all.sort((a, b) => a.bs - b.bs || a.who - b.who)

  const out = []
  let conflict = false
  const stable = (from, to) => {
    if (to > from) {
      const seg = base.slice(from, to)
      if (mode === 'regions') out.push(`stable ${seg.length}`)
      else out.push(...seg)
    }
  }
  const sides = [mine, theirs]
  let pos = 0, k = 0
  while (k < all.length) {
    const group = [all[k++]]
    const rs = group[0].bs
    let re = group[0].be
    while (k < all.length && all[k].bs <= re) {
      re = Math.max(re, all[k].be)
      group.push(all[k++])
    }
    stable(pos, rs)
    pos = re
    const baseLines = base.slice(rs, re)
    const rep = []
    for (let w = 0; w < 2; w++) {
      const cs = group.filter(c => c.who === w)
      if (!cs.length) { rep.push(baseLines); continue }
      const bmin = Math.min(...cs.map(c => c.bs)), bmax = Math.max(...cs.map(c => c.be))
      const smin = Math.min(...cs.map(c => c.ss)), smax = Math.max(...cs.map(c => c.se))
      rep.push(sides[w].slice(smin - (bmin - rs), smax + (re - bmax)))
    }
    const [m, t] = rep
    let label, res
    if (group.length === 1) {
      label = group[0].who ? 'theirs' : 'mine'
      res = rep[group[0].who]
    } else if (eq(m, t)) { label = 'both'; res = m }
    else if (eq(m, baseLines)) { label = 'theirs'; res = t }
    else if (eq(t, baseLines)) { label = 'mine'; res = m }
    else label = 'conflict'
    if (label === 'conflict') {
      conflict = true
      if (mode === 'regions') out.push(`conflict mine=${m.length} base=${baseLines.length} theirs=${t.length}`)
      else {
        out.push('<<<<<<< mine', ...m)
        if (mode === 'merge') out.push('||||||| base', ...baseLines)
        out.push('=======', ...t, '>>>>>>> theirs')
      }
    } else if (mode === 'regions') out.push(`${label} ${res.length}`)
    else out.push(...res)
  }
  stable(pos, base.length)
  process.stdout.write(out.map(l => l + '\n').join(''))
  process.exitCode = conflict ? 1 : 0
}

main()
