  let i = 0
  let j = 0
  let bs = 0
  let ss = 0
  const flush = () => {
    if (i > bs || j > ss) out.push({ who, bs, be: i, ss, se: j })
  }
  while (i < n || j < m) {
    if (i < n && j < m && base[i] === side[j]) {
      flush()
      i++
      j++
      bs = i
      ss = j
    } else if (j >= m || (i < n && L[i + 1][j] >= L[i][j + 1])) {
