const sorted = [...cells.values()].sort((x, y) => cmpAddr(x.addr, y.addr))
for (const c of sorted) {
  if (c.content[0] === '=') c.ast = parseFormula(c.content.slice(1))
}

let out = ''
if (mode === 'values') {
  const vals = evaluateAll(cells)
  for (const c of sorted) {
    const k = addrName(c.addr)
    out += `${k}=${vals.get(k)}\n`
  }
} else {
  for (const c of sorted) {
    let line = addrName(c.addr) + ':'
    if (c.ast) {
      const seen = new Map()
      for (const r of c.ast.refs) {
        const list = r.length === 2 ? expandRange(r[0], r[1]) : [r[0]]
        for (const a of list) seen.set(addrName(a), a)
      }
      for (const a of [...seen.values()].sort(cmpAddr)) line += ' ' + addrName(a)
    }
    out += line + '\n'
  }
}
process.stdout.write(out)
"}

{"file_path":"src/addr.js","content":"export function parseAddr(word) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(word)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  let col = 0
  for (const ch of m[1].toUpperCase()) col = col * 26 + (ch.charCodeAt(0) - 64)
  return { col, row }
}

export function addrName(a) {
  let c = a.col
  let s = ''
  while (c > 0) {
    const r = (c - 1) % 26
    s = String.fromCharCode(65 + r) + s
    c = (c - 1 - r) / 26
  }
  return s + a.row
}

export function cmpAddr(a, b) {
  return a.col - b.col || a.row - b.row
}

export function expandRange(a, b) {
  const out = []
  const c1 = Math.min(a.col, b.col), c2 = Math.max(a.col, b.col)
  const r1 = Math.min(a.row, b.row), r2 = Math.max(a.row, b.row)
  for (let c = c1; c <= c2; c++) for (let r = r1; r <= r2; r++) out.push({ col: c, row: r })
  return out
}
"}

{"file_path":"src/parse.js","content":"import { parseAddr } from './addr.js'

class Fail extends Error {}

function tokenize(src) {
  const toks = []
  let i = 0
  while (i < src.length) {
    const ch = src[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i))) && /[0-9]/.test(ch)) {
      toks.push({ k: 'num', v: Number(m[0]) })
      i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(src.slice(i)))) {
      toks.push({ k: 'word', v: m[0] })
      i += m[0].length
    } else if ((m = /^(<>|<=|>=|[=<>+\-*\/^(),:])/.exec(src.slice(i)))) {
      toks.push({ k: 'op', v: m[0] })
      i += m[0].length
    } else throw new Fail()
  }
  return toks
}

export function parseFormula(src) {
  const refs = []
  try {
    const toks = tokenize(src)
    let p = 0
    let misplaced = false
    const isOp = (v, o = 0) => toks[p + o] && toks[p + o].k === 'op' && toks[p + o].v === v
    const addRef = (w) => {
      const a = parseAddr(w)
      return a
    }
    const range = (w1, w2) => {
      const a = parseAddr(w1), b = parseAddr(w2)
      if (a && b) refs.push([a, b])
      return { t: 'range', a, b }
    }
    const cmp = () => {
      let l = add()
      while (['=', '<>', '<', '<=', '>', '>='].some((o) => isOp(o))) {
        const op = toks[p++].v
        l = { t: 'bin', op, l, r: add() }
      }
      return l
    }
    const add = () => {
      let l = mul()
      while (isOp('+') || isOp('-')) {
        const op = toks[p++].v
        l = { t: 'bin', op, l, r: mul() }
      }
      return l
    }
    const mul = () => {
      let l = pow()
      while (isOp('*') || isOp('/')) {
        const op = toks[p++].v
        l = { t: 'bin', op, l, r: pow() }
      }
      return l
    }
    const pow = () => {
      const l = unary()
      if (isOp('^')) {
        p++
        return { t: 'bin', op: '^', l, r: pow() }
      }
      return l
    }
    const unary = () => {
      if (isOp('-') || isOp('+')) {
        const op = toks[p++].v
        return { t: 'neg', op, e: unary() }
      }
      return primary()
    }
    const primary = () => {
      const t = toks[p]
      if (!t) throw new Fail()
      if (t.k === 'num') { p++; return { t: 'lit', v: { t: 'n', v: t.v } } }
      if (isOp('(')) {
        p++
        const e = cmp()
        if (!isOp(')')) throw new Fail()
        p++
        return e
      }
      if (t.k !== 'word') throw new Fail()
      if (isOp('(', 1)) {
        p += 2
        const args = []
        if (isOp(')')) p++
        else {
          for (;;) {
            if (toks[p] && toks[p].k === 'word' && isOp(':', 1) && toks[p + 2] && toks[p + 2].k === 'word' &&
              (isOp(',', 3) || isOp(')', 3))) {
              args.push(range(toks[p].v, toks[p + 2].v))
              p += 3
            } else args.push(cmp())
            if (isOp(',')) { p++; continue }
            if (isOp(')')) { p++; break }
            throw new Fail()
          }
        }
        return { t: 'call', name: t.v.toUpperCase(), args }
      }
      p++
      const up = t.v.toUpperCase()
      if (isOp(':') && toks[p + 1] && toks[p + 1].k === 'word') {
        const w2 = toks[p + 1].v
        p += 2
        range(t.v, w2)
        misplaced = true
        return { t: 'lit', v: { t: 'e', v: '#ERR!' } }
      }
      if (up === 'TRUE') return { t: 'lit', v: { t: 'b', v: true } }
      if (up === 'FALSE') return { t: 'lit', v: { t: 'b', v: false } }
      const a = addRef(t.v)
      if (a) { refs.push([a]); return { t: 'ref', a } }
      return { t: 'lit', v: { t: 'e', v: '#REF!' } }
    }
    const e = cmp()
    if (p !== toks.length) throw new Fail()
    return { ok: true, e: misplaced ? { t: 'lit', v: { t: 'e', v: '#ERR!' } } : e, refs }
  } catch (err) {
    if (err instanceof Fail) return { ok: false, e: { t: 'lit', v: { t: 'e', v: '#ERR!' } }, refs: [] }
    throw err
  }
}
"}

{"file_path":"src/eval.js","content":"import { addrName, expandRange } from './addr.js'

const ERRORS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])
const err = (v) => ({ t: 'e', v })
const num = (v) => ({ t: 'n', v })

function toNumber(x) {
  if (x.t === 'n') return x
  if (x.t === 'b') return num(x.v ? 1 : 0)
  if (x.t === 'e') return x
  return err('#VALUE!')
}

function fin(v) {
  return Number.isFinite(v) ? num(v) : err('#DIV/0!')
}

function codepoints(s) {
  return Array.from(s, (c) => c.codePointAt(0))
}

function compare(a, b) {
  const rank = { n: 0, s: 1, b: 2 }
  if (a.t !== b.t) return rank[a.t] - rank[b.t]
  if (a.t === 'n') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  if (a.t === 'b') return Number(a.v) - Number(b.v)
  const x = codepoints(a.v), y = codepoints(b.v)
  for (let i = 0; i < Math.min(x.length, y.length); i++) if (x[i] !== y[i]) return x[i] < y[i] ? -1 : 1
  return x.length - y.length
}

export function format(v) {
  if (v.t === 'n') return String(Number(v.v.toPrecision(10)))
  if (v.t === 'b') return v.v ? 'TRUE' : 'FALSE'
  return String(v.v)
}

export function evaluateAll(cells) {
  const memo = new Map()
  const busy = new Set()

  const cellValue = (a) => {
    const k = addrName(a)
    if (memo.has(k)) return memo.get(k)
    const c = cells.get(k)
    if (!c) return num(0)
    if (busy.has(k)) return err('#CYCLE!')
    busy.add(k)
    let v
    if (c.ast) v = ev(c.ast.e)
    else if (c.content === '') v = num(0)
    else if (/^-?[0-9]+(\.[0-9]+)?$/.test(c.content)) v = num(Number(c.content))
    else if (ERRORS.has(c.content)) v = err(c.content)
    else v = { t: 's', v: c.content }
    busy.delete(k)
    memo.set(k, v)
    return v
  }

  const ev = (n) => {
    switch (n.t) {
      case 'lit': return n.v
      case 'ref': return cellValue(n.a)
      case 'neg': {
        const x = toNumber(ev(n.e))
        if (x.t === 'e') return x
        return num(n.op === '-' ? -x.v : x.v)
      }
      case 'bin': {
        const l = ev(n.l)
        if (l.t === 'e') return l
        const r = ev(n.r)
        if (r.t === 'e') return r
        if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
          const c = compare(l, r)
          const res = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[n.op]
          return { t: 'b', v: res }
        }
        const a = toNumber(l)
        if (a.t === 'e') return a
        const b = toNumber(r)
        if (b.t === 'e') return b
        switch (n.op) {
          case '+': return fin(a.v + b.v)
          case '-': return fin(a.v - b.v)
          case '*': return fin(a.v * b.v)
          case '/': return b.v === 0 ? err('#DIV/0!') : fin(a.v / b.v)
          default: return fin(Math.pow(a.v, b.v))
        }
      }
      case 'call': return call(n)
    }
  }

  const call = (n) => {
    const { name, args } = n
    const known = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF']
    if (!known.includes(name)) return err('#NAME?')
    if (name === 'ABS' || name === 'IF') {
      if (args.length !== (name === 'ABS' ? 1 : 3)) return err('#ERR!')
      if (args.some((a) => a.t === 'range')) return err('#ERR!')
      if (name === 'ABS') {
        const x = toNumber(ev(args[0]))
        return x.t === 'e' ? x : num(Math.abs(x.v))
      }
      const c = ev(args[0])
      if (c.t === 'e') return c
      let truth
      if (c.t === 'b') truth = c.v
      else if (c.t === 'n') truth = c.v !== 0
      else return err('#VALUE!')
      return ev(truth ? args[1] : args[2])
    }
    if (args.length < 1) return err('#ERR!')
    const vals = []
    for (const a of args) {
      if (a.t === 'range') {
        if (!a.a || !a.b) vals.push(err('#REF!'))
        else for (const x of expandRange(a.a, a.b)) vals.push(cellValue(x))
      } else vals.push(ev(a))
    }
    const e = vals.find((v) => v.t === 'e')
    if (e) return e
    if (name === 'COUNT') return num(vals.filter((v) => v.t === 'n').length)
    const nums = []
    for (const v of vals) {
      const x = toNumber(v)
      if (x.t === 'e') return x
      nums.push(x.v)
    }
    switch (name) {
      case 'SUM': return fin(nums.reduce((s, x) => s + x, 0))
      case 'MIN': return num(Math.min(...nums))
      case 'MAX': return num(Math.max(...nums))
      default: return fin(nums.reduce((s, x) => s + x, 0) / nums.length)
    }
  }

  const out = new Map()
  for (const k of cells.keys()) out.set(k, format(cellValue(cells.get(k).addr)))
  return out
}
"}

