{"file_path":"src/cli.js","content":"#!/usr/bin/env node
import { readFileSync } from 'node:fs'
import { parseFormula } from './parse.js'
import { evaluateAll } from './eval.js'
import { parseAddr, addrName, cmpAddr, expandRange } from './addr.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const s = lines[i].replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') continue
  const raw = /^[^ \t]*/.exec(s)[0]
  const content = s.slice(raw.length).replace(/^[ \t]+/, '')
  const a = parseAddr(raw)
  if (!a) {
    process.stderr.write(`error: line ${i + 1}: invalid cell address ${raw}\n`)
    process.exit(2)
  }
  const key = addrName(a)
  if (cells.has(key)) {
    process.stderr.write(`error: line ${i + 1}: cell ${raw} is declared twice\n`)
    process.exit(2)
  }
  cells.set(key, { addr: a, content })
}

const sorted = [...cells.values()].sort((x, y) => cmpAddr(x.addr, y.addr))
for (const c of sorted) {
  if (c.content[0] === '=') c.ast = parseFormula(c.content.slice(1))
}

let out = ''
if (mode === 'values') {
  const vals = evaluateAll(cells)
  for (const c of sorted) {
    const k = addrName(c.addr)
    out += `${k}=${vals.get(k)}\n`
  }
} else {
  for (const c of sorted) {
    let line = addrName(c.addr) + ':'
    if (c.ast) {
      const seen = new Map()
      for (const r of c.ast.refs) {
        const list = r.length === 2 ? expandRange(r[0], r[1]) : [r[0]]
        for (const a of list) seen.set(addrName(a), a)
      }
      for (const a of [...seen.values()].sort(cmpAddr)) line += ' ' + addrName(a)
    }
    out += line + '\n'
  }
}
process.stdout.write(out)
"}

