import { readFileSync } from 'node:fs'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>', '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']

class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
  }
}

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdChar = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'

function scan(text) {
  const s = Array.from(text)
  const n = s.length
  const tokens = []
  let i = 0, line = 1, col = 1

  const adv = () => {
    const c = s[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }
  const fail = (l, c, r) => { throw new ScanError(l, c, r) }

  // consume a run of digits (pred) allowing single _ between digits
  const run = (pred) => {
    let any = false
    while (i < n) {
      if (pred(s[i])) { adv(); any = true }
      else if (s[i] === '_' && any && pred(s[i + 1])) adv()
      else break
    }
    return any
  }

  while (i < n) {
    const c = s[i]
    const sl = line, sc = col
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    if (c === '/' && s[i + 1] === '/') {
      while (i < n && s[i] !== '\n') adv()
      continue
    }
    if (c === '/' && s[i + 1] === '*') {
      adv(); adv()
      let depth = 1
      while (i < n && depth > 0) {
        if (s[i] === '/' && s[i + 1] === '*') { adv(); adv(); depth++ }
        else if (s[i] === '*' && s[i + 1] === '/') { adv(); adv(); depth-- }
        else adv()
      }
      if (depth > 0) fail(sl, sc, 'unterminated block comment')
      continue
    }
    if (c === 'r' && s[i + 1] === '"') {
      adv(); adv()
      let v = ''
      while (i < n && s[i] !== '"') v += adv()
      if (i >= n) fail(sl, sc, 'unterminated string')
      adv()
      tokens.push([sl, sc, 'rawstring', JSON.stringify(v)])
      continue
    }
    if (isIdStart(c)) {
      let t = ''
      while (i < n && isIdChar(s[i])) t += adv()
      tokens.push([sl, sc, KEYWORDS.has(t) ? 'keyword' : 'ident', t])
      continue
    }
    if (isDigit(c)) {
      let t0 = i
      let ok = true
      const p = s[i + 1]
      if (c === '0' && p !== undefined && 'xXbBoO'.includes(p)) {
        adv(); adv()
        const pred = 'xX'.includes(p) ? isHex : 'bB'.includes(p) ? isBin : isOct
        ok = run(pred)
      } else {
        run(isDigit)
        if (s[i] === '.' && isDigit(s[i + 1])) { adv(); run(isDigit) }
        if (s[i] === 'e' || s[i] === 'E') {
          if (isDigit(s[i + 1]) || ((s[i + 1] === '+' || s[i + 1] === '-') && isDigit(s[i + 2]))) {
            adv()
            if (!isDigit(s[i])) adv()
            run(isDigit)
          }
        }
