import { readFileSync } from 'node:fs'

function fail(msg, code = 2) {
  process.stderr.write(msg + '\n')
  process.exit(code)
}

const args = process.argv.slice(2)
const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'
let mode = args[0]
let workers = 0
if ((mode === 'waves' || mode === 'explain') && args.length === 1) {
  // ok
} else if (mode === 'pack' && args.length === 2) {
  if (!/^[1-9][0-9]*$/.test(args[1])) fail('error: workers must be a positive integer')
  workers = Number(args[1])
} else fail(USAGE)

let input = ''
try { input = readFileSync(0, 'utf8') } catch { input = '' }
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cost = new Map()
const deps = new Map()
const depUses = []
const NAME = /^[A-Za-z0-9_.-]+$/
for (let i = 0; i < lines.length; i++) {
  const line = lines[i].trim()
  if (line === '' || line.startsWith('#')) continue
  const w = line.split(/\s+/)
  const n = i + 1
  if (w[0] === 'task') {
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!NAME.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (cost.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    cost.set(w[1], BigInt(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    depUses.push(w.slice(1))
  } else fail(`error: line ${n}: unknown directive ${w[0]}`)
}
for (const t of cost.keys()) deps.set(t, new Set())
for (const names of depUses) for (const x of names) if (!cost.has(x)) fail(`error: unknown task ${x}`)
for (const [t, ...ds] of depUses) for (const d of ds) deps.get(t).add(d)

const names = [...cost.keys()].sort()
const sdeps = new Map(names.map((t) => [t, [...deps.get(t)].sort()]))

// cycle detection
{
  const state = new Map()
  const stack = []
  const visit = (t) => {
    state.set(t, 1)
    stack.push(t)
    for (const d of sdeps.get(t)) {
      const s = state.get(d)
      if (s === 1) {
        const cyc = stack.slice(stack.indexOf(d)).concat(d)
        fail('error: cycle: ' + cyc.join(' -> '), 3)
      }
      if (!s) visit(d)
    }
    stack.pop()
    state.set(t, 2)
  }
  for (const t of names) if (!state.get(t)) visit(t)
}

const start = new Map(), finish = new Map(), depth = new Map()
const order = []
{
  const seen = new Set()
  const visit = (t) => {
    if (seen.has(t)) return
    seen.add(t)
    for (const d of sdeps.get(t)) visit(d)
    order.push(t)
  }
  names.forEach(visit)
}
let total = 0n
for (const t of order) {
  let s = 0n, d = 0
  for (const x of sdeps.get(t)) {
    if (finish.get(x) > s) s = finish.get(x)
    d = Math.max(d, depth.get(x) + 1)
  }
  start.set(t, s); finish.set(t, s + cost.get(t)); depth.set(t, d)
  if (finish.get(t) > total) total = finish.get(t)
}

let out = []
if (mode === 'waves') {
  const ws = []
  for (const t of names) (ws[depth.get(t)] ||= []).push(t)
  ws.forEach((w, k) => out.push(`wave ${k}: ${w.join(' ')}`))
  out.push(`total ${total}`)
} else if (mode === 'explain') {
  for (const t of names) out.push(`${t} start=${start.get(t)} finish=${finish.get(t)} depth=${depth.get(t)}`)
  out.push(`total ${total}`)
} else {
  const prio = new Map()
  const dependents = new Map(names.map((t) => [t, []]))
  for (const t of names) for (const d of sdeps.get(t)) dependents.get(d).push(t)
  for (const t of [...order].reverse()) {
    let m = 0n
    for (const x of dependents.get(t)) if (prio.get(x) > m) m = prio.get(x)
    prio.set(t, m + cost.get(t))
  }
  const cand = [...names].sort((a, b) => (prio.get(a) === prio.get(b) ? (a < b ? -1 : 1) : prio.get(a) > prio.get(b) ? -1 : 1))
  const done = new Map()
  const freeAt = Array(workers).fill(0n)
  const runs = Array.from({ length: workers }, () => [])
  let remaining = cand.length
  let t = 0n
  let makespan = 0n
  while (remaining > 0) {
    for (;;) {
      const w = freeAt.findIndex((f) => f <= t)
      if (w < 0) break
      const task = cand.find((c) => !done.has(c) && sdeps.get(c).every((d) => done.has(d) && done.get(d) <= t))
      if (task === undefined) break
      const f = t + cost.get(task)
      done.set(task, f)
      freeAt[w] = f
      runs[w].push(`${task}@${t}-${f}`)
      if (f > makespan) makespan = f
      remaining--
    }
    if (remaining === 0) break
    const next = freeAt.filter((f) => f > t)
    if (!next.length) break
    t = next.reduce((a, b) => (a < b ? a : b))
  }
  runs.forEach((r, i) => out.push(`worker ${i}:` + r.map((x) => ' ' + x).join('')))
  out.push(`makespan ${makespan}`)
}
process.stdout.write(out.join('\n') + '\n')
