  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const ch = String.fromCharCode(parseInt(h, 16))
    return /[A-Za-z0-9\-._~]/.test(ch) ? ch : '%' + h.toUpperCase()
  })
}

function removeDots(p) {
  let out = ''
  while (p.length) {
    if (p.startsWith('../')) p = p.slice(3)
    else if (p.startsWith('./')) p = p.slice(2)
    else if (p.startsWith('/./')) p = p.slice(2)
    else if (p === '/.') p = '/'
    else if (p.startsWith('/../') || p === '/..') {
      p = p === '/..' ? '/' : p.slice(3)
      out = out.slice(0, Math.max(0, out.lastIndexOf('/')))
    } else if (p === '.' || p === '..') p = ''
    else {
      const i = p.indexOf('/', 1)
      const seg = i < 0 ? p : p.slice(0, i)
      out += seg
      p = p.slice(seg.length)
    }
  }
  return out
}

const DEFAULTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

function normalize(r) {
  const scheme = r.scheme === undefined ? undefined : lowerAscii(r.scheme)
  let path = pct(r.path, 'path')
  let userinfo, host, port
  if (r.auth !== undefined) {
    const a = splitAuth(r.auth)
    if (a.userinfo !== undefined) userinfo = pct(a.userinfo, 'userinfo')
    host = lowerAscii(pct(a.host, 'host'))
    port = a.port
  }
  const query = r.query === undefined ? undefined : pct(r.query, 'query')
  const fragment = r.fragment === undefined ? undefined : pct(r.fragment, 'fragment')
  if (port !== undefined && (port === '' || (scheme in DEFAULTS && DEFAULTS[scheme] === port))) port = undefined
  path = removeDots(path)
  if (r.auth !== undefined && path === '') path = '/'
  let s = ''
  if (scheme !== undefined) s += scheme + ':'
  if (r.auth !== undefined) {
    s += '//'
    if (userinfo !== undefined) s += userinfo + '@'
    s += host
    if (port !== undefined) s += ':' + port
  }
  s += path
  if (query !== undefined) s += '?' + query
  if (fragment !== undefined) s += '#' + fragment
  return s
}

function resolve(base, ref) {
  if (base.scheme === undefined) throw new Fail('the base has no scheme')
  const t = {}
  if (ref.scheme !== undefined) {
    Object.assign(t, ref)
  } else if (ref.auth !== undefined) {
    Object.assign(t, ref, { scheme: base.scheme })
  } else {
    t.scheme = base.scheme
    t.auth = base.auth
    t.fragment = ref.fragment
    if (ref.path === '') {
      t.path = base.path
      t.query = ref.query !== undefined ? ref.query : base.query
    } else {
      t.query = ref.query
      if (ref.path.startsWith('/')) t.path = ref.path
      else if (base.auth !== undefined && base.path === '') t.path = '/' + ref.path
      else {
        const i = base.path.lastIndexOf('/')
        t.path = (i >= 0 ? base.path.slice(0, i + 1) : '') + ref.path
      }
    }
  }
  return t
}

function main() {
  const mode = process.argv.slice(2)
  if (mode.length !== 1 || (mode[0] !== 'normalize' && mode[0] !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const out = []
  try {
    lines.forEach((line, i) => {
      try {
        if (mode[0] === 'normalize') out.push(normalize(parse(line)))
        else {
          const sp = line.indexOf(' ')
          if (sp < 0) throw new Fail('expected a base and a reference')
          const t = resolve(parse(line.slice(0, sp)), parse(line.slice(sp + 1)))
          out.push(normalize(t))
        }
      } catch (e) {
        if (!(e instanceof Fail)) throw e
        const msg = ['path', 'userinfo', 'host', 'query', 'fragment'].includes(e.message)
          ? `the ${e.message} has a truncated percent-encoding` : e.message
        throw new Fail(`line ${i + 1}: ${msg}`)
      }
    })
  } catch (e) {
    if (!(e instanceof Fail)) throw e
    process.stderr.write(`error: ${e.message}\n`)
    process.exit(2)
  }
  if (out.length) process.stdout.write(out.join('\n') + '\n')
}

