import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const fail = (n, r) => { throw new Fail(`error: line ${n}: ${r}`) }
const NAME = /^[A-Za-z0-9_.\/:-]+$/
const INT = /^(0|[1-9][0-9]*)$/
const int = (n, field, s, least) => {
  if (!INT.test(s) || BigInt(s) < BigInt(least)) fail(n, `${field} must be an integer of at least ${least}`)
  return BigInt(s)
}

function advanceBucket(p, st, tick) {
  if (!st) return { num: p.capacity * p.per, last: tick }
  st.num += p.refill * (tick - st.last)
  const cap = p.capacity * p.per
  if (st.num > cap) st.num = cap
  st.last = tick
  return st
}

function run(text) {
  let lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const states = new Map() // policy name -> Map(key -> state)
  const out = []
  const stats = new Map()
  let started = false
  let prev = null
  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const f = line.split(/\s+/)
    const d = f[0]
    if (d === 'bucket' || d === 'window' || d === 'route') {
      if (started) fail(n, 'declarations must come before the first event')
    }
    if (d === 'bucket') {
      if (f.length !== 5) fail(n, 'expected bucket <name> <capacity> <refill> <per>')
      if (!NAME.test(f[1])) fail(n, `invalid policy name ${f[1]}`)
      const capacity = int(n, 'capacity', f[2], 1)
      const refill = int(n, 'refill', f[3], 0)
      const per = int(n, 'per', f[4], 1)
      if (policies.has(f[1])) fail(n, `policy ${f[1]} is declared twice`)
      policies.set(f[1], { name: f[1], kind: 'bucket', capacity, refill, per })
      states.set(f[1], new Map())
    } else if (d === 'window') {
      if (f.length !== 4) fail(n, 'expected window <name> <limit> <span>')
      if (!NAME.test(f[1])) fail(n, `invalid policy name ${f[1]}`)
      const limit = int(n, 'limit', f[2], 0)
      const span = int(n, 'span', f[3], 1)
      if (policies.has(f[1])) fail(n, `policy ${f[1]} is declared twice`)
      policies.set(f[1], { name: f[1], kind: 'window', limit, span })
      states.set(f[1], new Map())
    } else if (d === 'route') {
      if (f.length < 3) fail(n, 'expected route <prefix> <policy>...')
      if (!NAME.test(f[1])) fail(n, `invalid route prefix ${f[1]}`)
      if (routes.has(f[1])) fail(n, `prefix ${f[1]} is routed twice`)
      for (const p of f.slice(2)) if (!policies.has(p)) fail(n, `unknown policy ${p}`)
      routes.set(f[1], f.slice(2).map((p) => policies.get(p)))
    } else if (d === 'event') {
      if (f.length !== 3) fail(n, 'expected event <tick> <key>')
      const tick = int(n, 'tick', f[1], 0)
      if (!NAME.test(f[2])) fail(n, `invalid key ${f[2]}`)
      if (prev !== null && tick < prev) fail(n, `tick ${tick} is before tick ${prev}`)
      prev = tick
      started = true
      const key = f[2]
      let best = null
      for (const pre of routes.keys()) if (key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
      let denier = null
      if (best !== null) {
        const ps = routes.get(best)
        const cur = ps.map((p) => {
          const m = states.get(p.name)
          let st = m.get(key)
          if (p.kind === 'bucket') st = advanceBucket(p, st, tick)
          else {
            if (!st) st = { ticks: [] }
            st.ticks = st.ticks.filter((t) => t > tick - p.span)
          }
          m.set(key, st)
          return st
        })
        for (let j = 0; j < ps.length; j++) {
          const p = ps[j]
          const ok = p.kind === 'bucket' ? cur[j].num >= p.per : BigInt(cur[j].ticks.length) < p.limit
          if (!ok) { denier = p.name; break }
        }
        if (denier === null) {
          ps.forEach((p, j) => {
            if (p.kind === 'bucket') cur[j].num -= p.per
            else cur[j].ticks.push(tick)
          })
        }
      }
      const s = stats.get(key) || { a: 0, d: 0 }
      if (denier === null) s.a++; else s.d++
      stats.set(key, s)
      out.push(denier === null ? `${tick} ${key} allow` : `${tick} ${key} deny ${denier}`)
    } else {
      fail(n, `unknown directive ${d}`)
    }
  }
  if (mode === 'replay') return out.map((l) => l + '\n').join('')
  let a = 0, dn = 0, res = ''
  for (const k of [...stats.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))) {
    const s = stats.get(k)
    a += s.a; dn += s.d
    res += `${k} allowed=${s.a} denied=${s.d}\n`
  }
  return res + `total allowed=${a} denied=${dn}\n`
}

try {
  const text = readFileSync(0, 'utf8')
  process.stdout.write(run(text))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exitCode = 2
}
