{"file_path":"src/output.js","content":"function cmp(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d !== 0) return d
  }
  return x.length - y.length
}

const sortedKeys = (t) => [...t.map.keys()].sort(cmp)

function scalarJson(n) {
  if (n.t === 'integer') return n.v.toString()
  return JSON.stringify(n.v) ?? 'null'
}

function emit(n, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  if (n.t === 'table') {
    const ks = sortedKeys(n)
    if (ks.length === 0) return '{}'
    return '{\n' + ks.map((k) => `${pad}${JSON.stringify(k)}: ${emit(n.map.get(k), ind + 1)}`).join(',\n') + '\n' + end + '}'
  }
  if (n.t === 'array') {
    if (n.items.length === 0) return '[]'
    return '[\n' + n.items.map((i) => pad + emit(i, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  return scalarJson(n)
}

export const toJson = (root) => emit(root, 0) + '\n'

export function toKeys(root) {
  const lines = []
  const walk = (n, path) => {
    if (n.t === 'table') {
      for (const k of sortedKeys(n)) {
        const p = path === null ? k : `${path}.${k}`
        const c = n.map.get(k)
        lines.push(`${p} ${c.t}`)
        walk(c, p)
      }
    } else if (n.t === 'array') {
      n.items.forEach((c, i) => {
        const p = `${path}[${i}]`
        lines.push(`${p} ${c.t}`)
        walk(c, p)
      })
    }
  }
  walk(root, null)
  return lines.map((l) => l + '\n').join('')
}
"}

{"file_path":"src/parser.js","content":"export class ParseError extends Error {
  constructor(message, line) {
    super(message)
    this.line = line
  }
}

const newTable = () => ({ t: 'table', map: new Map(), header: false })
const isWs = (c) => c === ' ' || c === '\t'
const isNameChar = (c) => c !== undefined && /^[A-Za-z0-9_-]$/.test(c)
const fail = (m) => { throw new ParseError(m, 0) }

const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

class Line {
  constructor(s) {
    this.s = s
    this.i = 0
  }
  get c() { return this.s[this.i] }
  ws() { while (isWs(this.s[this.i])) this.i++ }
  atEnd() { const c = this.c; return c === undefined || c === '#' || c === ';' }
}

function parseString(L) {
  const q = L.c
  L.i++
  let out = ''
  if (q === "'") {
    const j = L.s.indexOf("'", L.i)
    if (j < 0) fail('unterminated string')
    out = L.s.slice(L.i, j)
    L.i = j + 1
    return out
  }
  for (;;) {
