const finish = new Map()
const depth = new Map()
const prio = new Map()
const dependents = new Map(names.map((k) => [k, []]))
for (const k of names) for (const d of dl.get(k)) dependents.get(d).push(k)
function calc(u) {
  if (finish.has(u)) return
  let s = 0n
  let dp = 0
  for (const d of dl.get(u)) {
    calc(d)
    if (finish.get(d) > s) s = finish.get(d)
    if (depth.get(d) + 1 > dp) dp = depth.get(d) + 1
  }
  start.set(u, s)
  finish.set(u, s + cost.get(u))
  depth.set(u, dp)
}
function pr(u) {
  if (prio.has(u)) return prio.get(u)
