    const w = line.split(/\s+/)
    const err = (m) => fail(`error: line ${n}: ${m}`)
    if (w[0] === 'candidates') {
      if (candidates !== null) err('candidates must be declared once, before any ballot')
      if (w.length < 2) err('expected candidates <name>...')
      const seen = new Set()
      for (const name of w.slice(1)) {
        if (!NAME.test(name)) err(`invalid candidate name ${name}`)
        if (seen.has(name)) err(`candidate ${name} is declared twice`)
        seen.add(name)
      }
      candidates = w.slice(1)
    } else if (w[0] === 'ballot') {
      if (candidates === null) err('candidates must be declared once, before any ballot')
      if (w.length < 3) err('expected ballot <count> <candidate>...')
      if (!COUNT.test(w[1])) err('count must be a positive integer')
      const seen = new Set()
      for (const name of w.slice(2)) {
        if (!candidates.includes(name)) err(`unknown candidate ${name}`)
        if (seen.has(name)) err(`candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: BigInt(w[1]), prefs: w.slice(2) })
    } else {
      err(`unknown directive ${w[0]}`)
    }
  }
  if (candidates === null) fail('error: no candidates')
  return { candidates, ballots }
