export function count({ candidates, ballots }) {
  const alive = new Set(candidates)
  const history = new Map(candidates.map((c) => [c, []]))
  const rounds = []
  for (;;) {
    const tally = new Map([...alive].map((c) => [c, 0n]))
    let active = 0n
    for (const b of ballots) {
      const pick = b.prefs.find((p) => alive.has(p))
      if (pick !== undefined) {
        tally.set(pick, tally.get(pick) + b.count)
        active += b.count
      }
    }
    let total = 0n
    for (const b of ballots) total += b.count
    for (const [c, v] of tally) history.get(c).push(v)
    const list = [...tally].sort((a, b) => (a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : 1))
    const round = { list, exhausted: total - active, eliminated: null }
    rounds.push(round)
    if (active === 0n) return { rounds, winner: null }
    if (list[0][1] * 2n > active) return { rounds, winner: list[0][0] }
    const min = list[list.length - 1][1]
    let tied = list.filter(([, v]) => v === min).map(([c]) => c)
    for (let r = 0; r < rounds.length && tied.length > 1; ) {
      const vs = tied.map((c) => history.get(c)[r])
      const lo = vs.reduce((a, b) => (b < a ? b : a))
      if (vs.every((v) => v === lo)) { r++; continue }
      tied = tied.filter((c) => history.get(c)[r] === lo)
      r = 0
    }
    tied.sort()
    const out = tied[tied.length - 1]
    round.eliminated = out
    alive.delete(out)
  }
}
